import React, { useState, useEffect } from 'react';

const COLORS = {
  bg: '#050505', card: '#111111', accent: '#3b82f6', 
  gold: '#fbbf24', text: '#ffffff', muted: '#94a3b8', 
  border: '#1e293b', success: '#10b981'
};

export default function App() {
  const [tab, setTab] = useState('dashboard');
  const [clientes, setClientes] = useState(() => {
    const salvo = localStorage.getItem('juris_v3_docs');
    return salvo ? JSON.parse(salvo) : [];
  });

  const [formDoc, setFormDoc] = useState({ nome: '', cpf: '', endereco: '', estadoCivil: 'Solteiro(a)' });

  useEffect(() => {
    localStorage.setItem('juris_v3_docs', JSON.stringify(clientes));
  }, [clientes]);

  // Função para "Gerar" o documento (Simulação de Impressão Profissional)
  const imprimirDocumento = (tipo) => {
    const conteudo = tipo === 'procuracao' 
      ? `PROCURAÇÃO AD JUDICIA\n\nOUTORGANTE: ${formDoc.nome}, CPF: ${formDoc.cpf}, residente em ${formDoc.endereco}.\n\nOUTORGADO: O presente advogado signatário...\n\nPODERES: Pelo presente instrumento o outorgante confere ao outorgado poderes para o foro em geral...`
      : `CONTRATO DE HONORÁRIOS\n\nCLÁUSULA 1ª: O contratado se compromete a prestar serviços advocatícios para ${formDoc.nome}...\n\nCLÁUSULA 2ª: Pelos serviços, o contratante pagará o valor de...`;
    
    const win = window.open('', '', 'width=800,height=600');
    win.document.write(`<html><body style="font-family: serif; padding: 50px; line-height: 1.6;">${conteudo.replace(/\n/g, '<br>')}</body></html>`);
    win.document.close();
    win.print();
  };

  return (
    <div style={s.app}>
      {/* SIDEBAR */}
      <aside style={s.sidebar}>
        <div style={s.brand}><div style={s.brandIcon}>J</div> JurisPRO</div>
        <nav style={s.nav}>
          <div style={s.navLink(tab === 'dashboard')} onClick={() => setTab('dashboard')}>📊 Dashboard</div>
          <div style={s.navLink(tab === 'docs')} onClick={() => setTab('docs')}>📄 Gerador de Docs</div>
          <div style={s.navLink(tab === 'financeiro')} onClick={() => setTab('financeiro')}>💰 Financeiro</div>
        </nav>
        <div style={s.userProfile}>
          <div style={s.avatar}>ADM</div>
          <div><div style={{fontSize: '14px'}}>SaaS Master</div><div style={{fontSize: '10px', color: COLORS.success}}>STATUS: ATIVO</div></div>
        </div>
      </aside>

      {/* CONTEÚDO */}
      <main style={s.content}>
        <header style={s.header}>
          <h2>{tab === 'dashboard' ? 'Painel de Controle' : 'Automação de Documentos'}</h2>
          <div style={s.dateBadge}>Sessão Segura: {new Date().toLocaleTimeString()}</div>
        </header>

        {tab === 'dashboard' && (
          <div style={s.dashboardGrid}>
            <div style={s.statCard}>
              <span style={{color: COLORS.muted}}>Documentos Gerados</span>
              <div style={{fontSize: '32px', fontWeight: 'bold', color: COLORS.gold}}>128</div>
            </div>
            <div style={s.statCard}>
              <span style={{color: COLORS.muted}}>Eficiência Operacional</span>
              <div style={{fontSize: '32px', fontWeight: 'bold', color: COLORS.accent}}>+85%</div>
            </div>
            <div style={{...s.card, gridColumn: 'span 2'}}>
              <h4>Resumo de Performance</h4>
              <div style={{display: 'flex', gap: '10px', alignItems: 'flex-end', height: '100px'}}>
                {[20, 50, 80, 40, 90, 30, 100].map((h, i) => <div key={i} style={{...s.bar, height: `${h}%`}} />)}
              </div>
            </div>
          </div>
        )}

        {tab === 'docs' && (
          <div style={{display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '30px'}}>
            <div style={s.card}>
              <h3>🛠️ Dados do Outorgante</h3>
              <input style={s.input} placeholder="Nome Completo" onChange={e => setFormDoc({...formDoc, nome: e.target.value})} />
              <input style={s.input} placeholder="CPF / CNPJ" onChange={e => setFormDoc({...formDoc, cpf: e.target.value})} />
              <input style={s.input} placeholder="Endereço Completo" onChange={e => setFormDoc({...formDoc, endereco: e.target.value})} />
              <select style={s.input} onChange={e => setFormDoc({...formDoc, estadoCivil: e.target.value})}>
                <option>Solteiro(a)</option>
                <option>Casado(a)</option>
                <option>Divorciado(a)</option>
              </select>
            </div>

            <div style={s.card}>
              <h3>⚡ Ações Rápidas</h3>
              <p style={{color: COLORS.muted, fontSize: '14px'}}>Clique para gerar o arquivo pronto para assinatura.</p>
              <button style={s.btnDoc} onClick={() => imprimirDocumento('procuracao')}>📄 GERAR PROCURAÇÃO</button>
              <button style={{...s.btnDoc, backgroundColor: COLORS.gold, color: '#000'}} onClick={() => imprimirDocumento('contrato')}>📝 CONTRATO HONORÁRIOS</button>
              <button style={{...s.btnDoc, backgroundColor: '#444'}} onClick={() => alert("Função em breve!")}>📑 DECLARAÇÃO HIPOSSUFICIÊNCIA</button>
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

const s = {
  app: { display: 'flex', minHeight: '100vh', backgroundColor: COLORS.bg, color: COLORS.text, fontFamily: 'sans-serif' },
  sidebar: { width: '260px', backgroundColor: COLORS.card, borderRight: `1px solid ${COLORS.border}`, display: 'flex', flexDirection: 'column', padding: '20px' },
  brand: { display: 'flex', alignItems: 'center', gap: '12px', fontSize: '20px', fontWeight: 'bold', color: COLORS.accent, marginBottom: '40px' },
  brandIcon: { width: '35px', height: '35px', backgroundColor: COLORS.accent, color: 'white', display: 'flex', alignItems: 'center', justifyContent: 'center', borderRadius: '8px' },
  nav: { flex: 1 },
  navLink: (active) => ({ padding: '15px', borderRadius: '10px', cursor: 'pointer', marginBottom: '10px', backgroundColor: active ? 'rgba(59, 130, 246, 0.1)' : 'transparent', color: active ? COLORS.accent : COLORS.muted }),
  userProfile: { display: 'flex', alignItems: 'center', gap: '12px', padding: '20px 0', borderTop: `1px solid ${COLORS.border}` },
  avatar: { width: '40px', height: '40px', borderRadius: '50%', backgroundColor: COLORS.accent, display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 'bold' },
  content: { flex: 1, padding: '40px' },
